using UnityEngine;
using UnityEditor;
using System;
using System.IO;
using ConRoi.Investigation.V36.R104;
using Object = UnityEngine.Object;

namespace Unity.AI.Assistant.Agent.Dynamic.Extension.Editor
{
    internal class CommandScript : IRunCommand
    {
        public void Execute(ExecutionResult r)
        {
            var s = Object.FindFirstObjectByType<InvestigationSession>();
            if (!EditorApplication.isPlaying)
                throw new Exception("Play needed");
            s.Acquire("clip");
            s.OpenPage("clip");
            var w = EditorWindow.GetWindow(Type.GetType("UnityEditor.GameView,UnityEditor"));
            int index = 0;
            double next = EditorApplication.timeSinceStartup + .7;
            EditorApplication.CallbackFunction f = null;
            f = () =>
            {
                if (EditorApplication.timeSinceStartup < next)
                    return;
                next = EditorApplication.timeSinceStartup + 1;
                switch (index++)
                {
                    case 0:
                        w.minSize = w.maxSize = new Vector2(1024, 597.2f);
                        w.position = new Rect(0, 0, 1024, 597.2f);
                        s.OpenPage("clip");
                        s.SendMessage("CancelReviewDrag", SendMessageOptions.DontRequireReceiver);
                        break;
                    case 1:
                        ScreenCapture.CaptureScreenshot("Test/BangChung/investigation_r104/clip-layout-720.png");
                        s.OpenPage("reconstruction");
                        break;
                    case 2:
                        ScreenCapture.CaptureScreenshot("Test/BangChung/investigation_r104/model-layout-720.png");
                        w.minSize = w.maxSize = new Vector2(1536, 885.2f);
                        w.position = new Rect(0, 0, 1536, 885.2f);
                        s.OpenPage("clip");
                        break;
                    case 3:
                        ScreenCapture.CaptureScreenshot("Test/BangChung/investigation_r104/clip-layout-1080.png");
                        s.OpenPage("reconstruction");
                        break;
                    case 4:
                        ScreenCapture.CaptureScreenshot("Test/BangChung/investigation_r104/model-layout-1080.png");
                        break;
                    default:
                        EditorApplication.update -= f;
                        w.minSize = w.maxSize = new Vector2(1024, 597.2f);
                        w.position = new Rect(0, 0, 1024, 597.2f);
                        File.WriteAllText("Test/KetQua/investigation_r104/ui-layout.txt", "API layout fixture only: clip/model at1280x720 and1920x1080; ScaleToFit keeps texture aspect. UI behavior verified separately.");
                        break;
                }
            };
            EditorApplication.update += f;
            r.Log("Focused layouts capture");
        }
    }
}

